using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Diagnostics;
public class OrganiserController : BaseController
{
    private readonly RaceDayApiClient _api; public OrganiserController(RaceDayApiClient api) => _api = api;
    public async Task<IActionResult> Index() { var g = Require("Organiser"); if (g != null) return g; var (d, e, o) = await _api.Send<List<EventDto>>(HttpMethod.Get, "api/events/mine"); ViewBag.Error = o ? null : e; return View(d ?? new()); }
    public IActionResult Create() => Require("Organiser") ?? View(new EventVm());
    [HttpPost] public async Task<IActionResult> Create(EventVm vm) { var g = Require("Organiser"); if (g != null) return g; if (!ModelState.IsValid) return View(vm); var (d, e, o) = await _api.Send<EventDto>(HttpMethod.Post, "api/events", new { name = vm.Name, description = vm.Description, eventDate = vm.EventDate, location = vm.Location, distanceKm = vm.DistanceKm, eventTypeId = vm.EventTypeId }); if (!o || d == null) { ModelState.AddModelError("", e); return View(vm); } if (vm.Banner != null) { var (up, ue) = await _api.UploadPost($"api/events/{d.EventId}/banner", vm.Banner); if (!up) TempData["Error"] = "Event created, but banner upload failed: " + ue; } TempData["Success"] = "Event created."; return RedirectToAction(nameof(Index)); }
    public async Task<IActionResult> Edit(int id) { var g = Require("Organiser"); if (g != null) return g; var (d, e, o) = await _api.Send<EventDto>(HttpMethod.Get, $"api/events/{id}"); if (!o || d == null) { TempData["Error"] = e; return RedirectToAction(nameof(Index)); } return View(new EventVm { EventId = d.EventId, Name = d.Name, Description = d.Description, EventDate = d.EventDate, Location = d.Location, DistanceKm = d.DistanceKm, EventTypeId = d.EventTypeId }); }
    [HttpPost] public async Task<IActionResult> Edit(EventVm vm) { var g = Require("Organiser"); if (g != null) return g; if (!ModelState.IsValid) return View(vm); var (d, e, o) = await _api.Send<EventDto>(HttpMethod.Put, $"api/events/{vm.EventId}", new { name = vm.Name, description = vm.Description, eventDate = vm.EventDate, location = vm.Location, distanceKm = vm.DistanceKm, eventTypeId = vm.EventTypeId }); if (!o) { ModelState.AddModelError("", e); return View(vm); } if (vm.Banner != null) { var (up, ue) = await _api.Upload($"api/events/{vm.EventId}/banner", vm.Banner); if (!up) TempData["Error"] = ue; } TempData["Success"] = "Event updated."; return RedirectToAction(nameof(Index)); }
    [HttpPost] public async Task<IActionResult> Delete(int id) { var g = Require("Organiser"); if (g != null) return g; var (_, e, o) = await _api.Send<object>(HttpMethod.Delete, $"api/events/{id}"); TempData[o ? "Success" : "Error"] = o ? "Event deleted." : e; return RedirectToAction(nameof(Index)); }
    public async Task<IActionResult> Categories(int id) { var g = Require("Organiser"); if (g != null) return g; var (d, e, o) = await _api.Send<List<CategoryDto>>(HttpMethod.Get, $"api/events/{id}/categories"); ViewBag.EventId = id; ViewBag.Error = o ? null : e; return View(d ?? new()); }
    [HttpPost] public async Task<IActionResult> AddCategory(int id, CategoryVm vm) { var g = Require("Organiser"); if (g != null) return g; var (_, e, o) = await _api.Send<CategoryDto>(HttpMethod.Post, $"api/events/{id}/categories", new { name = vm.Name, description = vm.Description, minAge = vm.MinAge, maxAge = vm.MaxAge, distanceKm = vm.DistanceKm }); TempData[o ? "Success" : "Error"] = o ? "Category added." : e; return RedirectToAction(nameof(Categories), new { id }); }
    public async Task<IActionResult> Enrolments(int id) { var g = Require("Organiser"); if (g != null) return g; var (d, e, o) = await _api.Send<List<EnrolmentDto>>(HttpMethod.Get, $"api/events/{id}/enrolments"); ViewBag.EventId = id; ViewBag.Error = o ? null : e; return View(d ?? new()); }
    [HttpPost] public async Task<IActionResult> CaptureResult(ResultVm vm) { var g = Require("Organiser"); if (g != null) return g; var (_, e, o) = await _api.Send<ResultDto>(HttpMethod.Post, $"api/enrolments/{vm.EnrolmentId}/result", new { finishTimeSeconds = vm.FinishTimeSeconds, finishPosition = vm.FinishPosition, totalFinishers = vm.TotalFinishers }); TempData[o ? "Success" : "Error"] = o ? "Result published." : e; return RedirectToAction(nameof(Index)); }
}


